#!/bin/bash
# Task 179-w22-skewtable -- meshsim sim/ WORKER22 (branch sim-w22; P4, inventory C3).
# NetTest's skewtable step on the C++: suite_net (tests/suite_net.cpp on W20's harness; clang, the suite build, as
# the Makefile builds it) run as v1.3's run_tests.sh runs `NetTest -1 skewtable 40`, its output byte for byte against
# v1.3's log (tests/p4suites/skewtable.log, made by Quest 176). Also the NetTest groups ported so far (structure,
# unicast, routes, in-order random and the queue peaks, full rate, fan-in) against the net, net-quick, net-shuf and
# net-shuf2 logs (tests/p4_lines.sh: a partial run's lines as one block of the log). No Java. Not timing (the step's
# time is recorded only to plan). From an embedded kit (the sim tree without ref/, oracle/, planning/, pipeline/ and
# the large fixtures). Writes only results/179-w22-skewtable/. Scratch in /tmp, removed first and at the end.
# Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/179-w22-skewtable; mkdir -p "$RES"
W=/tmp/w22-179; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "bd69e3d9deef0313578fbdf0334be5defded022b33cc6bc55b8e5f0750b03f1b" ] || { echo "kit sha256 mismatch (want bd69e3d9deef0313578fbdf0334be5defded022b33cc6bc55b8e5f0750b03f1b)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KS=$W/kit/sim
FAIL=0
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
echo "kit: $(cat $W/kit/VERSION); host $(hostname); $(nproc) CPUs; $(clang++ --version | head -1); $(lscpu | grep 'Model name' | head -1)"
cd "$KS"
make MODE=suite build/clang-suite/suite_net -j8 > "$RES/build.log" 2>&1 && verdict build PASS || { tail -20 "$RES/build.log"; verdict build FAIL; echo FAILED; exit 1; }
B=build/clang-suite/suite_net
( t0=$(date +%s); $B -1 skewtable 40 > "$RES/skewtable.out" 2>&1; echo "skewtable: exit $? in $(( $(date +%s) - t0 )) s" > "$RES/skewtable.time" ) & ps=$!
for g in structure,unicast routes random fullrate fanin; do
  for s in "net -1" "net-quick -1 quick" "net-shuf 5 quick" "net-shuf2 11 quick"; do
    set -- $s; log=$1; shift
    if bash tests/p4_lines.sh tests/p4suites/$log.log $B "$@" --only=$g > "$W/o" 2>&1; then verdict "$log-$g" PASS; else verdict "$log-$g" FAIL; fi
    cat "$W/o"
  done
done
wait $ps; cat "$RES/skewtable.time"
cmp "$RES/skewtable.out" tests/p4suites/skewtable.log && verdict skewtable PASS || { diff tests/p4suites/skewtable.log "$RES/skewtable.out" | head -30; verdict skewtable FAIL; }
echo; cat "$RES/VERDICTS"
[ $FAIL = 0 ] && { echo DONE; exit 0; } || { echo FAILED; exit 1; }
